operations.command:
python -X utf8 -c "import sys,numpy as np,pandas as pd; from pathlib import Path; sys.path.insert(0,'experiments/compositional/jutul'); from spatial_tools import native_fields; r=Path('experiments/compositional/jutul/runs/baseline_tuned'); p=Path('experiments/compositional/jutul/diagnostics_baseline_mid'); ids,xyz,w=native_fields(); pv=np.fromfile(r/'porosity.bin')*np.fromfile(r/'volumes.bin'); p0=np.fromfile(r/'initial_Pressure.bin')/1e5; pressure=np.fromfile(p/'Pressure.bin')/1e5; sw0=np.fromfile(r/'initial_ImmiscibleSaturation.bin'); refs=pd.read_csv(p/'well_reference.csv').set_index('well'); m=pd.read_csv(p/'matched_partial.csv').groupby('well').tail(1).set_index('well');
for well in refs.index:
 c=w[w.well==well]; center=c[['x','y']].mean().to_numpy(); distance=np.sqrt(np.sum((xyz[:2].T-center)**2,axis=1)); mask=(distance>=500)&(distance<=1200)&(xyz[2]>=c.z.min())&(xyz[2]<=c.z.max())&(sw0<.99); background=refs.loc[well,'initial_pressure_pa']/1e5+np.average((pressure-p0)[mask],weights=pv[mask]); b=m.loc[well,'bhp_sim']; o=m.loc[well,'bhp_obs']; print(well,'annular_sample_count',int(mask.sum()),'reference_background_pressure',round(background,2),'simulated_drawdown',round(background-b,2),'target_drawdown',round(background-o,2),'estimated_Darcy_multiplier',round((background-b)/(background-o),3))"; $recent = Get-Content -LiteralPath 'experiments/compositional/jutul/runs/baseline_tuned/simulation_log.txt' -Encoding UTF8 -Tail 100; $recent | Select-String -Pattern 'completed_report_steps' | Select-Object -Last 1 | ForEach-Object {$_.Line}; Get-Date -Format o

